-- =============================================================================
-- IQRA Customer Management System (CMS) - pgAdmin 4 Setup Script
-- Generated with 1,000+ properly mapped Company and Contact records from Oracle APEX CMS
-- =============================================================================

-- Step 1: Ensure user 'postgres' password matches server/.env
ALTER USER postgres WITH PASSWORD 'postgres';

-- Step 2: DDL - Schema setup
DROP TABLE IF EXISTS contacts CASCADE;
DROP TABLE IF EXISTS companies CASCADE;

CREATE TABLE IF NOT EXISTS companies (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    technology VARCHAR(255),
    industry VARCHAR(255),
    city VARCHAR(255),
    country VARCHAR(255),
    website VARCHAR(500),
    existing_comp VARCHAR(10) DEFAULT 'N',
    da VARCHAR(255),
    phone VARCHAR(100),
    email VARCHAR(255),
    company_categories VARCHAR(255),
    company_type VARCHAR(100) DEFAULT 'Direct Client',
    employee_size VARCHAR(100),
    registered_url VARCHAR(500),
    registration_status VARCHAR(100),
    supplier_number VARCHAR(100),
    username VARCHAR(100),
    password VARCHAR(255),
    registration_date VARCHAR(100),
    source VARCHAR(255),
    remarks TEXT,
    salesperson VARCHAR(255),
    prev_salesperson VARCHAR(255),
    joget_id VARCHAR(100),
    contact_count INT DEFAULT 0,
    lead_count INT DEFAULT 0,
    normalized_website VARCHAR(500),
    created_by VARCHAR(100) DEFAULT 'system',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    modified_by VARCHAR(100) DEFAULT 'system',
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS contacts (
    id SERIAL PRIMARY KEY,
    company_id INT REFERENCES companies(id) ON DELETE SET NULL,
    company_name VARCHAR(255),
    contact_name VARCHAR(255) NOT NULL,
    designation VARCHAR(255),
    position_type VARCHAR(100),
    company_type VARCHAR(100),
    contact_status VARCHAR(100),
    salesperson VARCHAR(255),
    industry VARCHAR(255),
    country VARCHAR(255),
    website VARCHAR(500),
    phone VARCHAR(100),
    phone2 VARCHAR(100),
    phone3 VARCHAR(100),
    mobile VARCHAR(100),
    mobile2 VARCHAR(100),
    mobile3 VARCHAR(100),
    mobile_verified VARCHAR(50),
    email VARCHAR(255),
    other_email VARCHAR(255),
    email_verified VARCHAR(50),
    email_tool_verified VARCHAR(100),
    email_verified_response VARCHAR(100),
    linkedin_url VARCHAR(500),
    linkedin_id VARCHAR(100),
    comp_linkedin_id VARCHAR(100),
    preferred_linkedin_connected VARCHAR(255),
    linkedin_conn_send_acc VARCHAR(255),
    connection_date VARCHAR(100),
    connection_send_by VARCHAR(255),
    linkedin_connected_acc VARCHAR(255),
    priority_contact VARCHAR(100),
    current_past VARCHAR(100),
    source VARCHAR(255),
    source_details VARCHAR(255),
    data_extracted_date VARCHAR(100),
    technology VARCHAR(255),
    remarks TEXT,
    created_by VARCHAR(100) DEFAULT 'system',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    modified_by VARCHAR(100) DEFAULT 'system',
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

